const input=$input.first().json.body||$input.first().json;
const records=Array.isArray(input.records)?input.records:(input.record?[input.record]:[]);
const aliases={
 owner_name:['owner_name','owner','ownerName','property_owner','taxpayer_name','name'],
 property_address:['property_address','situs_address','situs','site_address','address','propertyAddress'],
 mailing_address:['mailing_address','owner_mailing_address','tax_mailing_address','mailingAddress'],
 city:['city','situs_city','property_city'],
 state:['state','state_code','situs_state','property_state'],
 zip:['zip','zipcode','zip_code','postal_code','situs_zip'],
 county:['county','county_name'],
 parcel_id:['parcel_id','parcelid','parcel_number','parcel_no','apn','pin','property_id','account_number'],
 property_type:['property_type','land_use','use_code','property_class','asset_type'],
 assessed_value:['assessed_value','total_assessed_value','assessed_total'],
 land_value:['land_value','assessed_land_value'],
 building_value:['building_value','improvement_value','assessed_improvement_value'],
 acreage:['acreage','lot_acres','acres','land_acres'],
 building_sqft:['building_sqft','living_area','sqft','square_feet','gross_building_area'],
 year_built:['year_built','built_year','construction_year'],
 sale_date:['sale_date','last_sale_date','deed_date'],
 sale_price:['sale_price','last_sale_price','deed_sale_price'],
 tax_status:['tax_status','tax_due_status','delinquent_status'],
 delinquent_tax_amount:['delinquent_tax_amount','delinquent_amount','tax_delinquent_amount'],
 zoning:['zoning','zoning_code'],
 legal_description:['legal_description','legal_desc']
};
const pick=(r,keys)=>{for(const k of keys){if(r[k]!==undefined&&r[k]!==null&&String(r[k]).trim()!=='') return r[k];}return null;};
const cleanText=v=>v==null?null:String(v).trim().replace(/\\s+/g,' ');
const cleanState=v=>{const s=cleanText(v); if(!s)return null; const m={'NORTH CAROLINA':'NC','SOUTH CAROLINA':'SC','VIRGINIA':'VA','TENNESSEE':'TN','GEORGIA':'GA','FLORIDA':'FL','NEW YORK':'NY','NEW JERSEY':'NJ','CALIFORNIA':'CA','TEXAS':'TX'}; return m[s.toUpperCase()]||s.toUpperCase();};
const cleanZip=v=>{const s=cleanText(v); if(!s)return null; const m=s.match(/\\d{5}(?:-\\d{4})?/); return m?m[0]:s;};
const num=v=>{if(v==null||v==='')return null; const n=Number(String(v).replace(/[$,\\s]/g,'')); return Number.isFinite(n)?n:null;};
const normalize=(r,i)=>{
 const n={};
 for(const [field,keys] of Object.entries(aliases)) n[field]=pick(r,keys);
 n.owner_name=cleanText(n.owner_name); n.property_address=cleanText(n.property_address); n.mailing_address=cleanText(n.mailing_address);
 n.city=cleanText(n.city); n.state=cleanState(n.state); n.zip=cleanZip(n.zip); n.county=cleanText(n.county);
 n.parcel_id=cleanText(n.parcel_id); n.property_type=cleanText(n.property_type); n.zoning=cleanText(n.zoning); n.legal_description=cleanText(n.legal_description);
 for(const f of ['assessed_value','land_value','building_value','acreage','building_sqft','year_built','sale_price','delinquent_tax_amount']) n[f]=num(n[f]);
 n.sale_date=cleanText(n.sale_date);
 n.source_url=cleanText(pick(r,['source_url','url','source','record_url']));
 n.source_name=cleanText(pick(r,['source_name','source_provider','provider']));
 n.source_type=cleanText(pick(r,['source_type','record_type','type']));
 n.source_record_id=cleanText(pick(r,['source_record_id','record_id','source_id','id']));
 n.source_observed_at=cleanText(pick(r,['source_observed_at','observed_at','retrieved_at']));
 n.distress_signals=Array.isArray(r.distress_signals)?[...new Set(r.distress_signals.map(cleanText).filter(Boolean))]:[];
 n.criterion_signals=(r.criterion_signals&&typeof r.criterion_signals==='object')?r.criterion_signals:{};
 n.criterion_evidence=Array.isArray(r.criterion_evidence)?r.criterion_evidence:[];
 n.raw_attributes=r.raw_attributes&&typeof r.raw_attributes==='object'?r.raw_attributes:r;
 const identityParts=[n.parcel_id,n.property_address,n.owner_name,n.city,n.state,n.zip].filter(Boolean).map(v=>String(v).toLowerCase().replace(/[^a-z0-9]+/g,'-'));
 n.normalized_identity_key=n.parcel_id?'parcel:'+n.parcel_id.toLowerCase().replace(/[^a-z0-9]+/g,''):('address:'+identityParts.join('|'));
 n.identity_complete=Boolean(n.owner_name&&n.property_address&&n.state&&(n.source_url||n.source_record_id));
 n.normalization_warnings=[];
 if(!n.owner_name)n.normalization_warnings.push('missing_owner_name');
 if(!n.property_address)n.normalization_warnings.push('missing_property_address');
 if(!n.state)n.normalization_warnings.push('missing_state');
 if(!(n.source_url||n.source_record_id))n.normalization_warnings.push('missing_source_identity');
 return {index:i,...n};
};
const normalized=records.filter(r=>r&&typeof r==='object').map(normalize);
const seen=new Set(); const deduped=[]; let duplicateCount=0;
for(const r of normalized){if(seen.has(r.normalized_identity_key)){duplicateCount++; continue;} seen.add(r.normalized_identity_key); deduped.push(r);}
return [{json:{success:true,request_id:input.request_id||null,record_count:deduped.length,input_record_count:normalized.length,duplicate_count:duplicateCount,records:deduped,policy:'Canonical normalization only. No missing facts are inferred; raw source attributes and provenance are preserved.'}}];
